import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"理查德·瑟斯","description":"","frontmatter":{"title":"理查德·瑟斯","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/理查德·瑟斯.md","filePath":"04_people/理查德·瑟斯.md"}'),i={name:"04_people/理查德·瑟斯.md"};function s(l,t,n,_,d,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="理查德·瑟斯-richard-sitts" tabindex="-1">理查德·瑟斯（Richard Sitts） <a class="header-anchor" href="#理查德·瑟斯-richard-sitts" aria-label="Permalink to &quot;理查德·瑟斯（Richard Sitts）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：航空顾问（Aviation Consultant）</li><li><strong>与巴菲特关系</strong>：伯克希尔航空业务顾问，为伯克希尔旗下NetJets等航空资产提供专业支持</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>理查德·瑟斯是伯克希尔·哈撒韦航空业务领域的重要顾问。伯克希尔旗下的航空业务涵盖多个板块，包括NetJets（全球领先的私人飞机产权共享公司）、FlightSafety（飞行培训公司）等。瑟斯凭借其深厚的航空专业背景和行业经验，为伯克希尔的航空投资决策提供关键支持。在巴菲特看来，航空业务是伯克希尔未来发展的战略重点之一，收购NetJets是伯克希尔最成功的收购案例之一。瑟斯在航空顾问岗位上，协助伯克希尔评估航空资产价值、优化运营效率，并为飞行安全标准提供专业建议。他的工作体现了巴菲特&quot;只与最优秀的人合作&quot;的管理哲学——即使在幕后顾问岗位上，伯克希尔也汇聚了行业顶尖的专业人才。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>NetJets被收购后</strong>：瑟斯作为航空顾问持续为伯克希尔提供专业支持</li><li><strong>航空业务整合期</strong>：在伯克希尔旗下多家航空公司的协同整合中发挥顾问作用</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p>',8)])])}const u=e(i,[["render",s]]);export{p as __pageData,u as default};
